SourceCode.Declaration:
/// <summary>
/// Whether an inventory or tracking dimension must be given for a receipt or an issue - the same
/// rule as the standard InventMovement.checkInventDimForInventDimField: an active dimension may be
/// left blank unless it is mandatory, or the direction does not allow it blank (Blank receipt
/// allowed / Blank issue allowed on the dimension group). Purchase receipt, transfer ship and
/// transfer receive (InventMov_Purch / _TransferFrom / _TransferTo) use those base rules
/// unchanged, so this matches what D365FO itself enforces at posting.
/// </summary>
class HSMobileOpsDimensionRules
{
}

Method.Source:
/// <summary>True when the dimension is active and may not be blank for this direction.</summary>
public static boolean mustSpecify(InventDimGroupSetup _setup, FieldId _dimensionField, boolean _receipt)
{
    InventDimGroupFieldSetup fieldSetup = _setup.getFieldSetup(_dimensionField);

    if (!fieldSetup.isActive())
    {
        return false;
    }
    return fieldSetup.isMandatory()
        || (_receipt ? !fieldSetup.isAllowBlankReceiptEnabled() : !fieldSetup.isAllowBlankIssueEnabled());
}

/// <summary>Serial number control: every unit carries its own serial number.</summary>
public static boolean serialPerUnit(InventDimGroupSetup _setup)
{
    return _setup.getFieldSetup(fieldNum(InventDim, InventSerialId)).isSerialNumberControlEnabled();
}
